  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Evento de comando
client.on(Events.InteractionCreate, async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({ content: 'No tienes permisos suficientes para usar este comando.', ephemeral: true });
    }

    if (!interaction.options.getMember('user')) {
      return interaction.reply({ content: 'Por favor, proporciona un usuario válido para banear.', ephemeral: true });
    }

    const member = interaction.options.getMember('user');

    await interaction.guild.members.ban(member, { days: 0, reason: `Comando /ban realizado por ${interaction.user.tag}` });

    return interaction.reply({ content: `Usuario ${member.user.tag} ha sido baneado.` });
  }
});

// Evento de carga
client.once(Events READY, () => {
  console.log(`Bot ${client.user.tag} listo para funcionar.`);
});

// Evento de error
client.on(Events ERROR, error => {
  console.error(error);
});

// Inicio del bot
client.login(token);
