4. Crear una función para inicializar el juego:

```c
Game* init_game() {
    Game* game = malloc(sizeof(Game));

    game->snake.size = 1;
    game->snake.x[0] = WINDOW_WIDTH / 2;
    game->snake.y[0] = WINDOW_HEIGHT / 2;

    game->window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        WINDOW_WIDTH,
        WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    game->renderer = SDL_CreateRenderer(
        game->window,
        -1,
        SDL_RENDERER_ACCELERATED
    );

    game->score = 0;
    game->speed = 10;
    game->running = true;

    game->food_x = rand() % (WINDOW_WIDTH / SQUARE_SIZE) * SQUARE_SIZE;
    game->food_y = rand() % (WINDOW_HEIGHT / SQUARE_SIZE) * SQUARE_SIZE;
    game->food_size = SQUARE_SIZE;

    return game;
}
```

5. Crear una función para actualizar el estado del juego:

```c
void update_game(Game* game) {
    // Mover la serpiente
    for (int I = game->snake.size - 1; I > 0; i--) {
        game->snake.x[i] = game->snake.x[i - 1];
        game->snake.y[i] = game->snake.y[i - 1];
    }

    switch (game->snake.x[0] / SQUARE_SIZE) {
        case 0:
            game->snake.x[0] = SQUARE_SIZE;
            break;
        case WINDOW_WIDTH / SQUARE_SIZE:
            game->snake.x[0] = WINDOW_WIDTH - SQUARE_SIZE;
            break;
        case (WINDOW_WIDTH / SQUARE_SIZE) - 1:
            game->snake.x[0] = WINDOW_WIDTH - SQUARE_SIZE * 2;
            break;
        default:
            game->snake.x[0] += SQUARE_SIZE;
            break;
    }

    switch (game->snake.y[0] / SQUARE_SIZE) {
        case 0:
            game->snake.y[0] = SQUARE_SIZE;
            break;
        case WINDOW_HEIGHT / SQUARE_SIZE:
            game->snake.y[0] = WINDOW_HEIGHT - SQUARE_SIZE;
            break;
        case (WINDOW_HEIGHT / SQUARE_SIZE) - 1:
            game->snake.y[0] = WINDOW_HEIGHT - SQUARE_SIZE * 2;
            break;
        default:
            game->snake.y[0] += SQUARE_SIZE;
            break;
    }

    // Comprobar si la serpiente se come a sí misma
    for (int I = 1; I < game->snake.size; i++) {
        if (game->snake.x[i] == game->snake.x[0] && game->snake.y[i] == game->snake.y[0]) {
            game->running = false;
        }
    }

    // Comprobar si la serpiente come la comida
    if (game->snake.x[0] == game->food_x && game->snake.y[0] == game->food_y) {
        game->score += 10;
        game->snake.size++;
        game->food_x = rand() % (WINDOW_WIDTH / SQUARE_SIZE) * SQUARE_SIZE;
        game->food_y = rand() % (WINDOW_HEIGHT / SQUARE_SIZE) * SQUARE_SIZE;
    }

    // Comprobar si la serpiente choca con las paredes
    if (game->snake.x[0] < 0 || game->snake.x[0] >= WINDOW_WIDTH || game->snake.y[0] < 0 || game->snake.y[0] >= WINDOW_HEIGHT) {
        game->running = false;
    }
}
```

