8. Crear una función para manejar los eventos de entrada:

```c
void handle_events(Game* game) {
    SDL_Event event;
    while (SDL_PollEvent(&event)) {
        switch (event.type) {
            case SDL_QUIT:
                game->running = false;
                break;
            case SDL_KEYDOWN:
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        if (game->snake.y[0] % SQUARE_SIZE != 0)
                            break;
                        game->snake.movement_y = -SQUARE_SIZE;
                        game->snake.movement_x = 0;
                        break;
                    case SDLK_DOWN:
                        if (game->snake.y[0] % SQUARE_SIZE != SQUARE_SIZE - 1)
                            break;
                        game->snake.movement_y = SQUARE_SIZE;
                        game->snake.movement_x = 0;
                        break;
                    case SDLK_LEFT:
                        if (game->snake.x[0] % SQUARE_SIZE != 0)
                            break;
                        game->snake.movement_x = -SQUARE_SIZE;
                        game->snake.movement_y = 0;
                        break;
                    case SDLK_RIGHT:
                        if (game->snake.x[0] % SQUARE_SIZE != SQUARE_SIZE - 1)
                            break;
                        game->snake.movement_x = SQUARE_SIZE;
                        game->snake.movement_y = 0;
                        break;
                }
                break;
        }
    }
}
```

